local function C_15()
local script = G2L["15"];
	local button = script.Parent

	mouse.MouseButton1Click:Connect(function()
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RequestCommand = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent

	RequestCommand:InvokeServer(";unfog")
	RequestCommand:InvokeServer(";fogcolor black")
	RequestCommand:InvokeServer(";time 0")

	local char = player.Character
	if not char then return end

	local tool
	for _, v in player:GetDescendants() do
		if v.Name == "SyncAPI" then
			tool = v.Parent
			break
		end
	end
	for _, v in game.ReplicatedStorage:GetDescendants() do
		if v.Name == "SyncAPI" then
			tool = v.Parent
			break
		end
	end

	if not tool then
		warn("F3X / Building Tools not found! Equip it first.")
		return
	end

	local remote = tool.SyncAPI.ServerEndpoint
	local function _(args)
		pcall(function()
			remote:InvokeServer(unpack(args))
		end)
	end

	local function SetName(part, name)
		local args = {[1] = "SetName", [2] = {part}, [3] = name}
		_(args)
	end

	local function SetCollision(part, boolean)
		local args = {[1] = "SyncCollision", [2] = {[1] = {["Part"] = part, ["CanCollide"] = boolean}}}
		_(args)
	end

	local function SetAnchor(boolean, part)
		local args = {[1] = "SyncAnchor", [2] = {[1] = {["Part"] = part, ["Anchored"] = boolean}}}
		_(args)
	end

	local function CreatePart(cf, parent)
		local args = {[1] = "CreatePart", [2] = "Normal", [3] = cf, [4] = parent}
		_(args)
	end

	local function MovePart(part, cf)
		local args = {[1] = "SyncMove", [2] = {[1] = {["Part"] = part, ["CFrame"] = cf}}}
		_(args)
	end

	local function Resize(part, size, cf)
		local args = {[1] = "SyncResize", [2] = {[1] = {["Part"] = part, ["CFrame"] = cf, ["Size"] = size}}}
		_(args)
	end

	local function AddMesh(part)
		local args = {[1] = "CreateMeshes", [2] = {[1] = {["Part"] = part}}}
		_(args)
	end

	local function SetMesh(part, meshid)
		local args = {[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["MeshId"] = "rbxassetid://" .. meshid}}}
		_(args)
	end

	local function SetTexture(part, texid)
		local args = {[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["TextureId"] = "rbxassetid://" .. texid}}}
		_(args)
	end

	local function MeshResize(part, size)
		local args = {[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["Scale"] = size}}}
		_(args)
	end

	local function VertexColormf(part)
		local args = {[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["VertexColor"] = Vector3.new(3,3,3)}}}
		_(args)
	end

	local function SetLocked(part, boolean)
		local args = {[1] = "SetLocked", [2] = {part}, [3] = boolean}
		_(args)
	end

	local function Sky(id)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then return end

		local e = root.CFrame.X
		local f = root.CFrame.Y
		local g = root.CFrame.Z

		CreatePart(CFrame.new(math.floor(e), math.floor(f), math.floor(g)) + Vector3.new(0, -9, 0), workspace.Terrain)
		wait(0.5)

		local skyPart
		for _, v in workspace:GetDescendants() do
			if v:IsA("BasePart") and v.CFrame.X == math.floor(e) and v.CFrame.Z == math.floor(g) then
				skyPart = v

				SetName(v, "Sky")
				AddMesh(v)
				SetMesh(v, "111891702759441")
				SetTexture(v, id)
				MeshResize(v, Vector3.new(20000, 20000, 20000))
				VertexColormf(v)
				SetLocked(v, true)

				local rotationSpeedX = 50
				local rotationSpeedY = 50
				local rotationSpeedZ = 50
				local currentRotation = Vector3.new(0, 0, 0)

				RunService.Heartbeat:Connect(function(deltaTime)
					currentRotation = Vector3.new(
						(currentRotation.X + rotationSpeedX * deltaTime) % 360,
						(currentRotation.Y + rotationSpeedY * deltaTime) % 360,
						(currentRotation.Z + rotationSpeedZ * deltaTime) % 360
					)

					local baseCFrame = CFrame.new(skyPart.Position)
					local rotatedCFrame = baseCFrame * CFrame.Angles(
						math.rad(currentRotation.X),
						math.rad(currentRotation.Y),
						math.rad(currentRotation.Z)
					)

					MovePart(skyPart, rotatedCFrame)
				end)

				print("Trippy Sky activated")
				break
			end
		end
	end

	Sky("116329731712353")
	end)
end;
