		end
		for _, v in ipairs(player.Character:GetChildren()) do
			if v:FindFirstChild("SyncAPI") then return v end
		end
		return nil
	end

	local f3x = getf3x()
	if not f3x then warn("where yo btools at?") return end

	local serverendpoint = f3x.SyncAPI.ServerEndpoint

	local BALL_NAME = "EpicBallOrbit_" .. player.Name
	local radius = 3.2
	local heightOffset = 0.5
	local speed = 2.3
	local ballSize = Vector3.new(2, 2, 2)  -- Smaller IORB as requested

	local ballPart = nil
	local connection = nil

	local function cleanupOldBall()
		local oldBall = workspace:FindFirstChild(BALL_NAME)
		if oldBall and serverendpoint then
			serverendpoint:InvokeServer("Remove", { [1] = oldBall })
		end
		ballPart = nil
	end

	local function createBall()
		cleanupOldBall()
		local character = player.Character
		if not character or not character:FindFirstChild("HumanoidRootPart") then return end
		local hrp = character.HumanoidRootPart
		local initialCFrame = hrp.CFrame * CFrame.new(0, heightOffset, radius)
		local createdPart = serverendpoint:InvokeServer("CreatePart", "Ball", initialCFrame, workspace)
		if not createdPart then return end
		ballPart = createdPart
