local function C_33()
local script = G2L["33"];
	local button = script.Parent

	mouse.MouseButton1Click:Connect(function()
		local player = Players.LocalPlayer

		local function getf3x()
			local backpack = player.Backpack
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then return v end
			end
			for _, v in ipairs(player.Character:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then return v end
			end
			return nil
		end

		local f3x = getf3x()
		if not f3x then warn("Equip F3X / BTools first!") return end

		local remote = f3x.SyncAPI.ServerEndpoint
		local function Send(args) 
			pcall(function()
				remote:InvokeServer(unpack(args)) 
			end)
		end

		local PAD_NAME = "FloatingPad_" .. player.Name

		local oldPad = workspace:FindFirstChild(PAD_NAME)
		if oldPad then
			Send({"Remove", {oldPad}})
		end

		local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
		if not hrp then warn("No HumanoidRootPart!") return end

		local padCF = CFrame.new(hrp.Position.X, hrp.Position.Y - 4, hrp.Position.Z)
		Send({"CreatePart", "Cylinder", padCF, workspace})

		local pad
		for _, v in workspace:GetChildren() do
			if v:IsA("BasePart") and (v.Position - Vector3.new(hrp.Position.X, hrp.Position.Y - 4, hrp.Position.Z)).Magnitude < 1 then
				pad = v
				break
			end
		end

		if pad then
			pad.Name = PAD_NAME
			Send({"SyncAnchor", {{Part = pad, Anchored = true}}})
			Send({"SetLocked", {pad}, true})
			Send({"SyncResize", {{Part = pad, Size = Vector3.new(8, 1.8, 8), CFrame = pad.CFrame}}})
			Send({"SyncColor", {{Part = pad, Color = Color3.fromRGB(147, 112, 219), UnionColoring = false}}})
			Send({"CreateMeshes", {{Part = pad}}})
			Send({"SyncMesh", {{Part = pad, Scale = Vector3.new(1, 1, 1)}}})

			spawn(function()
				while pad and pad.Parent do
					if hrp and hrp.Parent then
						local targetCF = CFrame.new(hrp.Position.X, hrp.Position.Y - 4, hrp.Position.Z)
						Send({"SyncMove", {{Part = pad, CFrame = targetCF}}})
					end
					wait()
				end
			end)

			print("Visible purple floating pad activated")
		else
			warn("Failed to find created pad!")
		end

		player.CharacterAdded:Connect(function(newChar)
			wait(1)
			local old = workspace:FindFirstChild(PAD_NAME)
			if old then
				Send({"Remove", {old}})
			end
		end)
	end)

	-- Draggable logic
	local dragging, dragInput, dragStart, startPos
	local function update(input)
		local delta = input.Position - dragStart
		gui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
	end

	gui.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = gui.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	gui.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)

	UserInputService.InputChanged:Connect(function(input)
		if input == dragInput and dragging then
			update(input)
		end
	end)

end;
